import ops,json,pathlib,subprocess,hashlib,importlib.util
r=ops.ROOT;rr=r/'rollback';spec=importlib.util.spec_from_file_location('ro',rr/'ops.py');ro=importlib.util.module_from_spec(spec);spec.loader.exec_module(ro)
supp=r/'supplement-private-uat';assert (supp/'demo.json').is_file()
h=hashlib.sha256((supp/'demo.json').read_bytes()).hexdigest();(r/'supplement-integrity.json').write_text(json.dumps({'source':'R2 stopped backend site private/uat/demo.json','sha256':h,'native_upload_backup_excluded_this_manifest':True,'private_only':True},indent=2))
ro.cmd(['docker','run','--name','centrochange-b99-r3-fit-supplement-rollback','--label','centrochange.mission=B99-R3','--network','none','--user','0','--memory','32m','--memory-swap','32m','--mount','type=bind,source='+str(supp)+',target=/supplement,readonly','--mount','type=volume,source='+ops.PROJECT+'-r3-fit-rollback-sites,target=/sites','--entrypoint','sh',ops.IMAGE,'-c','mkdir -p /sites/b99.local/private/uat && cp /supplement/demo.json /sites/b99.local/private/uat/demo.json && chown -R 1000:1000 /sites/b99.local/private/uat && chmod 600 /sites/b99.local/private/uat/demo.json'],'restore-private-uat-supplement')
out=ro.execute("print('ROLES='+json.dumps(frappe.get_all('Has Role',fields=['parent','parenttype','role'],order_by='parent, parenttype, role')));frappe.db.rollback();frappe.destroy()",'current-normalized-roles')
(r/'current-normalized-roles.json').write_text(next(x for x in out.splitlines() if x.startswith('ROLES=')).split('=',1)[1])
out=ro.execute("from centrochange_core.uat import demo\nprint('VALIDATION='+json.dumps(demo.validate(),default=str));frappe.db.rollback();frappe.destroy()",'rollback-demo-validation-supplemented');v=json.loads(next(x for x in out.splitlines() if x.startswith('VALIDATION=')).split('=',1)[1]);assert v['status']=='PASS'
out=ro.execute("from centrochange_core.operations.integration_acceptance import run\nprint('RESULT='+json.dumps(run(),default=str));frappe.db.rollback();frappe.destroy()",'rollback-operational-smoke');v=json.loads(next(x for x in out.splitlines() if x.startswith('RESULT=')).split('=',1)[1]);assert v['status']=='PASS'
(r/'rollback-status.json').write_text(json.dumps({'status':'PASS','real_native_restore':True,'full_schema_metadata_business_files_pins_reconciled':True,'private_uat_manifest_supplement_restored':True,'http_ping':200,'operational_smoke_checks':len(v['checks'])},indent=2));print('REAL ROLLBACK FUNCTIONAL PASS',flush=True)
